const remaining = (expiresAt, now = Date.now()) => Math.max(0, Math.ceil((Date.parse(expiresAt) - now) / 1000)) || 0;
const isPaid = session => session?.status === 'PAID' || session?.status === 'TICKET_ISSUED';
const isPending = session => session?.status === 'PENDING_PAYMENT';
const categoryNames = ['DIAMOND','SAPPHIRE','RUBY','PLATINUM','GOLD','SILVER'];
function sellable(seat, categories) {
  return seat.availability === 'AVAILABLE' && categories.some(c => c.id === seat.categoryId && categoryNames.includes(c.name) && Number.isSafeInteger(c.price) && c.price > 0);
}
function safeURL(value, {external = false} = {}) {
  if (typeof value !== 'string' || !value.trim()) return null;
  try { const url = new URL(value, globalThis.location?.href || 'http://localhost/');
    const origin = globalThis.location?.origin || 'http://localhost';
    return ((url.origin === origin && ['http:','https:'].includes(url.protocol)) || (external && url.protocol === 'https:')) ? url.href : null;
  } catch { return null; }
}

